-- Exact course-time matrix, relation rules, block priority variants and solver/validator hooks.
create table if not exists public.course_time_preferences(
 id uuid primary key default gen_random_uuid(), institution_code text not null default public.current_tenant_code() references public.institutions(institution_code) on delete restrict,
 course_id uuid not null references public.course_catalog(id) on delete cascade, weekday smallint not null check(weekday between 1 and 7), period smallint not null check(period between 1 and 20),
 mode text not null check(mode in('prefer','avoid','blocked')), weight integer not null default 10 check(weight between 0 and 1000), note text, active boolean not null default true, updated_at timestamptz not null default now(),
 unique(institution_code,course_id,weekday,period)
);
alter table public.course_time_preferences enable row level security;
drop policy if exists "course_time_preferences_read" on public.course_time_preferences; create policy "course_time_preferences_read" on public.course_time_preferences for select to authenticated using(public.tenant_row_allowed(institution_code));
drop policy if exists "course_time_preferences_manage" on public.course_time_preferences; create policy "course_time_preferences_manage" on public.course_time_preferences for all to authenticated using(public.tenant_row_allowed(institution_code) and public.has_any_module_permission('schedule')) with check(public.tenant_row_allowed(institution_code) and public.has_any_module_permission('schedule'));
create index if not exists idx_course_time_preferences_lookup on public.course_time_preferences(institution_code,course_id,weekday,period) where active;

create table if not exists public.schedule_relation_rules(
 id uuid primary key default gen_random_uuid(), institution_code text not null default public.current_tenant_code() references public.institutions(institution_code) on delete restrict,
 rule_type text not null check(rule_type in('same_day','different_day','same_slot','different_slot','not_adjacent','no_lunch_split')),
 left_requirement_id uuid not null references public.class_course_requirements(id) on delete cascade, right_requirement_id uuid references public.class_course_requirements(id) on delete cascade,
 lunch_after_period smallint check(lunch_after_period between 1 and 19), hard boolean not null default true, weight integer not null default 20 check(weight between 0 and 1000), note text, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 check((rule_type='no_lunch_split' and right_requirement_id is null and lunch_after_period is not null) or (rule_type<>'no_lunch_split' and right_requirement_id is not null and right_requirement_id<>left_requirement_id))
);
alter table public.schedule_relation_rules enable row level security;
drop policy if exists "schedule_relation_rules_read" on public.schedule_relation_rules; create policy "schedule_relation_rules_read" on public.schedule_relation_rules for select to authenticated using(public.tenant_row_allowed(institution_code));
drop policy if exists "schedule_relation_rules_manage" on public.schedule_relation_rules; create policy "schedule_relation_rules_manage" on public.schedule_relation_rules for all to authenticated using(public.tenant_row_allowed(institution_code) and public.has_any_module_permission('schedule')) with check(public.tenant_row_allowed(institution_code) and public.has_any_module_permission('schedule'));
create index if not exists idx_schedule_relation_left on public.schedule_relation_rules(institution_code,left_requirement_id) where active;
create index if not exists idx_schedule_relation_right on public.schedule_relation_rules(institution_code,right_requirement_id) where active and right_requirement_id is not null;

create or replace function public.course_slot_allowed_v1(p_course_id uuid,p_weekday smallint,p_period smallint) returns boolean language sql stable security definer set search_path=public as $$select not exists(select 1 from course_time_preferences x where x.institution_code=current_tenant_code() and x.course_id=p_course_id and x.weekday=p_weekday and x.period=p_period and x.mode='blocked' and x.active)$$;
create or replace function public.course_slot_penalty_v1(p_course_id uuid,p_weekday smallint,p_start smallint,p_block smallint) returns integer language sql stable security definer set search_path=public as $$select coalesce(sum(case x.mode when 'prefer' then -x.weight when 'avoid' then x.weight else 0 end),0)::integer from generate_series(p_start,p_start+p_block-1) g(period) left join course_time_preferences x on x.institution_code=current_tenant_code() and x.course_id=p_course_id and x.weekday=p_weekday and x.period=g.period and x.active$$;
create or replace function public.get_scenario_block_pattern_v1(p_requirement_id uuid,p_base smallint[],p_remaining integer,p_scenario_no smallint) returns smallint[] language plpgsql stable security definer set search_path=public as $$declare v_pattern smallint[];v_count int;v_offset int;begin select count(*) into v_count from course_block_preferences where institution_code=current_tenant_code() and class_course_requirement_id=p_requirement_id and active;if v_count>0 then v_offset:=least(greatest(p_scenario_no::int,1),v_count)-1;select block_pattern into v_pattern from course_block_preferences where institution_code=current_tenant_code() and class_course_requirement_id=p_requirement_id and active order by priority offset v_offset limit 1;end if;if coalesce(cardinality(v_pattern),0)=0 then v_pattern:=p_base;end if;if coalesce(cardinality(v_pattern),0)=0 then return '{}'::smallint[];end if;return normalize_schedule_block_pattern_v2(v_pattern,p_remaining);end$$;
create or replace function public.schedule_relation_slot_allowed_v1(p_scenario_id uuid,p_requirement_id uuid,p_weekday smallint,p_period smallint,p_block smallint) returns boolean language plpgsql stable security definer set search_path=public as $$declare r record;v_other uuid;v_other_day smallint;v_other_start smallint;begin for r in select * from schedule_relation_rules where institution_code=current_tenant_code() and active and hard and (left_requirement_id=p_requirement_id or right_requirement_id=p_requirement_id) loop if r.rule_type='no_lunch_split' then if p_period<=r.lunch_after_period and p_period+p_block-1>r.lunch_after_period then return false;end if;continue;end if;v_other:=case when r.left_requirement_id=p_requirement_id then r.right_requirement_id else r.left_requirement_id end;if not exists(select 1 from schedule_scenario_rows where scenario_id=p_scenario_id and requirement_id=v_other) then continue;end if;if r.rule_type='different_day' and exists(select 1 from schedule_scenario_rows where scenario_id=p_scenario_id and requirement_id=v_other and weekday=p_weekday) then return false;end if;if r.rule_type='same_day' and not exists(select 1 from schedule_scenario_rows where scenario_id=p_scenario_id and requirement_id=v_other and weekday=p_weekday) then return false;end if;if r.rule_type='different_slot' and exists(select 1 from schedule_scenario_rows where scenario_id=p_scenario_id and requirement_id=v_other and weekday=p_weekday and period between p_period and p_period+p_block-1) then return false;end if;if r.rule_type='not_adjacent' and exists(select 1 from schedule_scenario_rows where scenario_id=p_scenario_id and requirement_id=v_other and weekday=p_weekday and period in(p_period-1,p_period+p_block)) then return false;end if;if r.rule_type='same_slot' then select weekday,min(period)::smallint into v_other_day,v_other_start from schedule_scenario_rows where scenario_id=p_scenario_id and requirement_id=v_other group by weekday order by weekday limit 1;if v_other_day<>p_weekday or v_other_start<>p_period then return false;end if;end if;end loop;return true;end$$;
grant execute on function public.course_slot_allowed_v1(uuid,smallint,smallint),public.course_slot_penalty_v1(uuid,smallint,smallint,smallint),public.get_scenario_block_pattern_v1(uuid,smallint[],integer,smallint),public.schedule_relation_slot_allowed_v1(uuid,uuid,smallint,smallint,smallint) to authenticated;

create or replace function public.get_schedule_scenario_custom_rule_issues_v1(p_scenario_id uuid) returns table(code text,affected_count integer,detail text) language sql stable security definer set search_path=public as $$with blocked as (select count(*)::int n from schedule_scenario_rows s join course_time_preferences x on x.institution_code=s.institution_code and x.course_id=s.course_id and x.weekday=s.weekday and x.period=s.period and x.mode='blocked' and x.active where s.scenario_id=p_scenario_id),rel as(select * from schedule_relation_rules where institution_code=current_tenant_code() and active and hard),v as(select 'RELATION_DIFFERENT_DAY' code,count(*)::int n from rel r where r.rule_type='different_day' and exists(select 1 from schedule_scenario_rows a join schedule_scenario_rows b on b.scenario_id=a.scenario_id and b.requirement_id=r.right_requirement_id and b.weekday=a.weekday where a.scenario_id=p_scenario_id and a.requirement_id=r.left_requirement_id) union all select 'RELATION_SAME_DAY',count(*)::int from rel r where r.rule_type='same_day' and exists(select 1 from schedule_scenario_rows where scenario_id=p_scenario_id and requirement_id=r.left_requirement_id) and exists(select 1 from schedule_scenario_rows where scenario_id=p_scenario_id and requirement_id=r.right_requirement_id) and not exists(select 1 from schedule_scenario_rows a join schedule_scenario_rows b on b.scenario_id=a.scenario_id and b.requirement_id=r.right_requirement_id and b.weekday=a.weekday where a.scenario_id=p_scenario_id and a.requirement_id=r.left_requirement_id) union all select 'RELATION_DIFFERENT_SLOT',count(*)::int from rel r where r.rule_type='different_slot' and exists(select 1 from schedule_scenario_rows a join schedule_scenario_rows b on b.scenario_id=a.scenario_id and b.requirement_id=r.right_requirement_id and b.weekday=a.weekday and b.period=a.period where a.scenario_id=p_scenario_id and a.requirement_id=r.left_requirement_id) union all select 'RELATION_SAME_SLOT',count(*)::int from rel r where r.rule_type='same_slot' and exists(select 1 from schedule_scenario_rows where scenario_id=p_scenario_id and requirement_id=r.left_requirement_id) and exists(select 1 from schedule_scenario_rows where scenario_id=p_scenario_id and requirement_id=r.right_requirement_id) and not exists(select 1 from schedule_scenario_rows a join schedule_scenario_rows b on b.scenario_id=a.scenario_id and b.requirement_id=r.right_requirement_id and b.weekday=a.weekday and b.period=a.period where a.scenario_id=p_scenario_id and a.requirement_id=r.left_requirement_id) union all select 'RELATION_NOT_ADJACENT',count(*)::int from rel r where r.rule_type='not_adjacent' and exists(select 1 from schedule_scenario_rows a join schedule_scenario_rows b on b.scenario_id=a.scenario_id and b.requirement_id=r.right_requirement_id and b.weekday=a.weekday and abs(b.period-a.period)=1 where a.scenario_id=p_scenario_id and a.requirement_id=r.left_requirement_id) union all select 'RELATION_LUNCH_SPLIT',count(*)::int from rel r where r.rule_type='no_lunch_split' and exists(select 1 from schedule_scenario_rows a where a.scenario_id=p_scenario_id and a.requirement_id=r.left_requirement_id and a.block_key is not null group by a.block_key having min(a.period)<=r.lunch_after_period and max(a.period)>r.lunch_after_period)) select 'COURSE_TIME_SLOT_BLOCKED',n,'Ders zaman matrisinde yasaklanan hücrelere yerleşen dersler.' from blocked where n>0 union all select code,n,'Özel ders ilişki kuralı ihlali.' from v where n>0$$;
create or replace function public.get_current_custom_rule_issues_v1() returns table(severity text,code text,affected_count integer,detail text) language sql stable security definer set search_path=public as $$with blocked as (select count(*)::int n from teacher_schedule s join course_time_preferences x on x.institution_code=s.institution_code and x.course_id=s.course_id and x.weekday=s.weekday and x.period=s.period and x.mode='blocked' and x.active where s.active and tenant_row_allowed(s.institution_code)),rel as(select * from schedule_relation_rules where institution_code=current_tenant_code() and active and hard),v as(select 'RELATION_DIFFERENT_DAY' code,count(*)::int n from rel r where r.rule_type='different_day' and exists(select 1 from teacher_schedule a join teacher_schedule b on b.active and b.class_course_requirement_id=r.right_requirement_id and b.weekday=a.weekday where a.active and a.class_course_requirement_id=r.left_requirement_id) union all select 'RELATION_SAME_DAY',count(*)::int from rel r where r.rule_type='same_day' and exists(select 1 from teacher_schedule where active and class_course_requirement_id=r.left_requirement_id) and exists(select 1 from teacher_schedule where active and class_course_requirement_id=r.right_requirement_id) and not exists(select 1 from teacher_schedule a join teacher_schedule b on b.active and b.class_course_requirement_id=r.right_requirement_id and b.weekday=a.weekday where a.active and a.class_course_requirement_id=r.left_requirement_id) union all select 'RELATION_DIFFERENT_SLOT',count(*)::int from rel r where r.rule_type='different_slot' and exists(select 1 from teacher_schedule a join teacher_schedule b on b.active and b.class_course_requirement_id=r.right_requirement_id and b.weekday=a.weekday and b.period=a.period where a.active and a.class_course_requirement_id=r.left_requirement_id) union all select 'RELATION_SAME_SLOT',count(*)::int from rel r where r.rule_type='same_slot' and exists(select 1 from teacher_schedule where active and class_course_requirement_id=r.left_requirement_id) and exists(select 1 from teacher_schedule where active and class_course_requirement_id=r.right_requirement_id) and not exists(select 1 from teacher_schedule a join teacher_schedule b on b.active and b.class_course_requirement_id=r.right_requirement_id and b.weekday=a.weekday and b.period=a.period where a.active and a.class_course_requirement_id=r.left_requirement_id) union all select 'RELATION_NOT_ADJACENT',count(*)::int from rel r where r.rule_type='not_adjacent' and exists(select 1 from teacher_schedule a join teacher_schedule b on b.active and b.class_course_requirement_id=r.right_requirement_id and b.weekday=a.weekday and abs(b.period-a.period)=1 where a.active and a.class_course_requirement_id=r.left_requirement_id) union all select 'RELATION_LUNCH_SPLIT',count(*)::int from rel r where r.rule_type='no_lunch_split' and exists(select 1 from teacher_schedule a where a.active and a.class_course_requirement_id=r.left_requirement_id and a.block_key is not null group by a.block_key having min(a.period)<=r.lunch_after_period and max(a.period)>r.lunch_after_period)) select 'error','COURSE_TIME_SLOT_BLOCKED',n,'Ders zaman matrisinde yasaklanan hücrelere yerleşen dersler.' from blocked where n>0 union all select 'error',code,n,'Özel ders ilişki kuralı ihlali.' from v where n>0$$;
grant execute on function public.get_schedule_scenario_custom_rule_issues_v1(uuid),public.get_current_custom_rule_issues_v1() to authenticated;
create or replace function public.get_schedule_scenario_hard_issues_v2(p_scenario_id uuid) returns table(code text,affected_count integer,detail text) language sql stable security definer set search_path=public as $$select * from public.get_schedule_scenario_hard_issues_pre_phase3(p_scenario_id) union all select * from public.get_schedule_phase3_scenario_issues_v1(p_scenario_id) union all select * from public.get_schedule_scenario_custom_rule_issues_v1(p_scenario_id)$$;
create or replace function public.get_schedule_integrity_report() returns table(severity text,code text,affected_count integer,detail text) language sql stable security definer set search_path=public as $$select * from public.get_schedule_integrity_report_pre_phase3() union all select * from public.get_schedule_phase3_current_issues_v1() union all select * from public.get_current_custom_rule_issues_v1()$$;

-- Production generator patch is intentionally signature-guarded. It adds exact course-slot blocking,
-- relation-rule candidate filtering, per-course time preference scoring and scenario-specific block patterns.
do $$declare d text;old text;new text;begin d:=pg_get_functiondef('public.generate_schedule_scenarios()'::regprocedure);if position('course_slot_allowed_v1' in d)=0 then old:='if exists(select 1 from public.teacher_unavailability u where u.teacher_id=v_member.teacher_id and u.weekday=d and u.period=p+k and u.active=true) then sync_ok:=false;exit;end if;';new:=old||E'\n              if not public.course_slot_allowed_v1(v_member.course_id,d,(p+k)::smallint) or not public.schedule_relation_slot_allowed_v1(v_scenario,v_member.requirement_id,d,p,v_member.block_hours) then sync_ok:=false;exit;end if;';if position(old in d)=0 then raise exception 'PATCH_SYNC_SLOT_NOT_FOUND';end if;d:=replace(d,old,new);old:='sync_candidate:=sync_candidate+pref;';new:='sync_candidate:=sync_candidate+pref+public.course_slot_penalty_v1(v_member.course_id,d,p,v_member.block_hours);';if position(old in d)=0 then raise exception 'PATCH_SYNC_SCORE_NOT_FOUND';end if;d:=replace(d,old,new);old:='v_pattern:=case when v_has_rule and cardinality(v_rule.block_pattern)>0 then public.normalize_schedule_block_pattern_v2(v_rule.block_pattern,v_remaining) else ''{}''::smallint[] end;';new:='v_pattern:=public.get_scenario_block_pattern_v1(v_item.requirement_id,case when v_has_rule then v_rule.block_pattern else ''{}''::smallint[] end,v_remaining,v_no);';if position(old in d)=0 then raise exception 'PATCH_BLOCK_NOT_FOUND';end if;d:=replace(d,old,new);old:='if exists(select 1 from public.teacher_unavailability u where u.teacher_id=v_item.teacher_id and u.weekday=d and u.period=p+k and u.active=true) then bad:=true;exit;end if;';new:=old||E'\n              if not public.course_slot_allowed_v1(v_item.course_id,d,(p+k)::smallint) or not public.schedule_relation_slot_allowed_v1(v_scenario,v_item.requirement_id,d,p,v_block) then bad:=true;exit;end if;';if position(old in d)=0 then raise exception 'PATCH_ITEM_SLOT_NOT_FOUND';end if;d:=replace(d,old,new);old:='candidate:=pref+(v_hash%9)+greatest(p+v_block-1-6,0)*2;';new:='candidate:=pref+public.course_slot_penalty_v1(v_item.course_id,d,p,v_block)+(v_hash%9)+greatest(p+v_block-1-6,0)*2;';if position(old in d)=0 then raise exception 'PATCH_ITEM_SCORE_NOT_FOUND';end if;d:=replace(d,old,new);execute d;end if;end$$;
